using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace MacroExecute
{
    internal sealed class TestDesktop : IImageDesktop, IDisposable
    {
        public Bitmap Scene=new Bitmap(12,8,PixelFormat.Format32bppArgb);
        public Rectangle Bounds {get{return new Rectangle(-20,10,12,8);}}
        public Rectangle Foreground {get{return new Rectangle(-15,14,7,4);}}
        public Point Cursor {get;private set;}
        public List<Point> Clicks=new List<Point>();
        public int Captures,AppearAfter,CaptureDelayMs;public Action<string> OnEvent;
        public TestDesktop(){using(var g=Graphics.FromImage(Scene))g.Clear(Color.Black);Scene.SetPixel(10,6,Color.Red);Scene.SetPixel(11,7,Color.Lime);}
        public Bitmap Capture(Rectangle area){Captures++;if(CaptureDelayMs>0)Thread.Sleep(CaptureDelayMs);if(AppearAfter>0 && Captures<AppearAfter){var blank=new Bitmap(area.Width,area.Height);using(var g=Graphics.FromImage(blank))g.Clear(Color.Black);return blank;}return Scene.Clone(new Rectangle(area.X-Bounds.X,area.Y-Bounds.Y,area.Width,area.Height),PixelFormat.Format32bppArgb);}
        public void Move(Point p){Cursor=p;}
        public void Button(MouseButton b,bool up){if(!up)Clicks.Add(Cursor);if(OnEvent!=null)OnEvent("mouse:"+(up?"up:":"down:")+b); }
        public void Dispose(){Scene.Dispose();}
    }
    internal static class FeatureTests
    {
        private static System.Collections.Generic.IEnumerable<System.Windows.Forms.Control> Descendants(System.Windows.Forms.Control parent){foreach(System.Windows.Forms.Control child in parent.Controls){yield return child;foreach(var nested in Descendants(child))yield return nested;}}
        private static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
        private static Step Image(ActionKind kind){using(var b=new Bitmap(2,2,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(b))g.Clear(Color.Black);b.SetPixel(0,0,Color.Red);b.SetPixel(1,1,Color.Lime);return new Step{Kind=kind,ImageData=ImageTemplate.Encode(b),TimeoutMs=30,PollMs=10,MoveToMatch=false};}}
        private static void Run(WindowsHost host,params Step[] steps){new Runner(host).Run(Plan.Build(new Macro{Steps=steps.ToList()},AppDomain.CurrentDomain.BaseDirectory),1,1,CancellationToken.None).GetAwaiter().GetResult();}
        public static void Run(Action<string,Action> test,string directory)
        {
            test("Multi-image ANY stops before loading later references",delegate{using(var d=new TestDesktop()){var step=Image(ActionKind.FindImage);step.AdditionalImages=new[]{"not base64"};var session=new ImageSession(d);Check(session.SearchOnce(step,CancellationToken.None).HasValue&&d.Captures==1,"ANY failed to short circuit");}});
            test("Multi-image fallback finds second reference and preserves its position",delegate{using(var d=new TestDesktop())using(var absent=new Bitmap(1,1)){absent.SetPixel(0,0,Color.Blue);var step=Image(ActionKind.FindImage);string hit=step.ImageData;step.ImageData=ImageTemplate.Encode(absent);step.AdditionalImages=new[]{hit,"not base64"};Check(new ImageSession(d).SearchOnce(step,CancellationToken.None)==new Point(-9,17)&&d.Captures==1,"Ordered fallback failed");}});
            test("Multi-image ALL clears stale results and stops on first miss",delegate{using(var d=new TestDesktop())using(var absent=new Bitmap(1,1)){absent.SetPixel(0,0,Color.Blue);var step=Image(ActionKind.FindImage);step.RequireAllImages=true;var session=new ImageSession(d);Check(session.SearchOnce(step,CancellationToken.None).HasValue,"Initial match missing");step.AdditionalImages=new[]{ImageTemplate.Encode(absent),"not base64"};Check(!session.SearchOnce(step,CancellationToken.None).HasValue&&!session.LastMatch.HasValue,"Partial ALL retained match");}});
            test("Multi-image ALL uses one snapshot and clicks only once",delegate{using(var d=new TestDesktop()){var step=Image(ActionKind.ClickImage);step.RequireAllImages=true;step.AdditionalImages=new[]{step.ImageData,step.ImageData};Run(new WindowsHost(null,d),step);Check(d.Captures==1&&d.Clicks.Count==1&&d.Clicks[0]==new Point(-9,17),"ALL clicked multiple times or changed target");}});
            test("Multi-image nested IF restores outer match",delegate{using(var d=new TestDesktop())using(var absent=new Bitmap(1,1)){absent.SetPixel(0,0,Color.Blue);var outer=Image(ActionKind.IfImage);outer.AdditionalImages=new[]{outer.ImageData};var inner=Image(ActionKind.IfImage);inner.RequireAllImages=true;inner.AdditionalImages=new[]{ImageTemplate.Encode(absent)};Run(new WindowsHost(null,d),outer,inner,new Step{Kind=ActionKind.Else},new Step{Kind=ActionKind.Note},new Step{Kind=ActionKind.EndIf},new Step{Kind=ActionKind.MouseClick,Pointer=PointerMode.LastMatch},new Step{Kind=ActionKind.EndIf});Check(d.Clicks.Single()==new Point(-9,17),"Nested image list lost outer scope");}});
            test("Multi-image references roundtrip and clone independently",delegate{var step=Image(ActionKind.FindImage);step.RequireAllImages=true;step.AdditionalImages=new[]{step.ImageData};var clone=step.Clone();clone.AdditionalImages[0]="changed";Check(step.AdditionalImages[0]==step.ImageData,"Clone aliases image list");var saved=Storage.Decode(Storage.Encode(new Macro{Steps=new List<Step>{step}})).Steps[0];Check(saved.RequireAllImages&&saved.AdditionalImages.SequenceEqual(step.AdditionalImages),"Saved image list changed");ImageTemplate.ValidateReferences(saved);});
            test("Multi-image editor exposes ordered list and ALL toggle headlessly",delegate{var context=SynchronizationContext.Current;try{using(var editor=new StepEditor(Image(ActionKind.IfImage),directory)){HeadlessUi.Render(editor,Path.Combine(directory,"multi-image-editor.png"));Check(Descendants(editor).Any(c=>c.AccessibleName=="Ordered reference images"),"Image list missing");Check(Descendants(editor).Any(c=>c.Text=="Require ALL reference images"),"Mode toggle missing");HeadlessUi.Render(editor,Path.Combine(directory,"multi-image-editor.png"));Check(!editor.Visible,"Editor opened a window");}}finally{SynchronizationContext.SetSynchronizationContext(context);}});
            test("Image timeout includes capture and matching time",delegate{using(var d=new TestDesktop()){d.CaptureDelayMs=60;d.AppearAfter=2;try{Run(new WindowsHost(null,d),Image(ActionKind.ClickImage));throw new Exception("Search continued after timeout.");}catch(TimeoutException){}Check(d.Captures==1&&d.Clicks.Count==0,"Slow capture was excluded from timeout.");}});
            test("Image wait pause prevents capture and click until resumed",delegate{using(var d=new TestDesktop()){var host=new WindowsHost(null,d);var runner=new Runner(host){Paused=true};var plan=Plan.Build(new Macro{Steps=new List<Step>{Image(ActionKind.ClickImage)}},directory);var task=runner.Run(plan,1,1,CancellationToken.None);Task.Delay(60).GetAwaiter().GetResult();Check(d.Captures==0&&d.Clicks.Count==0,"Paused search sent input.");runner.Paused=false;task.GetAwaiter().GetResult();Check(d.Clicks.Count==1,"Resume did not complete click.");}});
            test("Missing wait timeout raises error without clicks",delegate{using(var d=new TestDesktop()){d.AppearAfter=int.MaxValue;var host=new WindowsHost(null,d);try{Run(host,Image(ActionKind.ClickImage));throw new Exception("Timeout ignored.");}catch(TimeoutException){}Check(d.Clicks.Count==0&&!host.Images.LastMatch.HasValue,"Timeout retained a result.");}});
            test("Missing nested ELSE cannot click stale outer result",delegate{using(var d=new TestDesktop()){var host=new WindowsHost(null,d);var missing=Image(ActionKind.IfImage);missing.SearchIn=SearchArea.Rectangle;missing.X=-20;missing.Y=10;missing.Width=2;missing.Height=2;try{Run(host,Image(ActionKind.IfImage),missing,new Step{Kind=ActionKind.Else},new Step{Kind=ActionKind.MouseClick,Pointer=PointerMode.LastMatch},new Step{Kind=ActionKind.EndIf},new Step{Kind=ActionKind.EndIf});throw new Exception("Stale result was usable.");}catch(InvalidOperationException){}Check(d.Clicks.Count==0,"Clicked stale result.");}});
            test("Nested IF insertion and block copying stay balanced",delegate{var steps=EditorBlocks.Create(Image(ActionKind.IfImage));steps.InsertRange(1,EditorBlocks.Create(Image(ActionKind.IfImage)));var macro=new Macro{Steps=steps};Plan.Build(macro,directory);Check(EditorBlocks.End(steps,0)==5&&EditorBlocks.End(steps,1)==3,"Wrong block ranges.");var copy=EditorBlocks.Copy(steps,0);steps.AddRange(copy);Plan.Build(macro,directory);Check(steps.Count==12,"Nested block copy incomplete.");steps.RemoveRange(0,6);Plan.Build(macro,directory);});
            test("Duplicating a block isolates its labels and jumps",delegate{var steps=new List<Step>{new Step{Kind=ActionKind.Repeat},new Step{Kind=ActionKind.Label,Text="loop"},new Step{Kind=ActionKind.Jump,Text="loop"},new Step{Kind=ActionKind.EndRepeat}};steps.AddRange(EditorBlocks.Copy(steps,0));Plan.Build(new Macro{Steps=steps},directory);Check(steps[5].Text==steps[6].Text&&steps[5].Text!="loop","Copied jump not remapped.");});
            test("Randomized repeat count stays inside inclusive bounds",delegate{var h=new FakeHost();new Runner(h).Run(Plan.Build(new Macro{Steps=new List<Step>{new Step{Kind=ActionKind.Repeat,Count=2,CountMax=4},new Step{Kind=ActionKind.TypeText},new Step{Kind=ActionKind.EndRepeat}}},directory),1,1,CancellationToken.None).GetAwaiter().GetResult();Check(h.Calls.Count>=2&&h.Calls.Count<=4,"Random repeat out of range.");});
            test("Invalid randomized ranges rejected",delegate{try{Storage.Validate(new Macro{Steps=new List<Step>{new Step{Kind=ActionKind.Delay,DelayMs=100,DelayMaxMs=10}}});throw new Exception("Bad range accepted.");}catch(InvalidDataException){}});
            test("Explicit desktop search ignores old rectangle coordinates",delegate{using(var d=new TestDesktop()){var s=Image(ActionKind.ClickImage);s.SearchIn=SearchArea.Desktop;s.X=-20;s.Y=10;s.Width=1;s.Height=1;Run(new WindowsHost(null,d),s);Check(d.Clicks.Count==1,"Desktop search unexpectedly cropped.");}});
            test("Legacy JSON retains defaults and original action IDs",delegate{var macro=Storage.Decode("{\"SchemaVersion\":1,\"Name\":\"old\",\"Steps\":[{\"Kind\":23,\"Target\":\"ref.png\"},{\"Kind\":27}]}");Check(macro.Steps[0].Kind==ActionKind.IfImage&&macro.Steps[0].PollMs==100&&macro.Steps[0].SearchIn==SearchArea.Legacy,"Legacy action/default changed.");Plan.Build(macro,directory);});
            test("Image click uses match center at desktop right/bottom edge",delegate{using(var d=new TestDesktop()){var s=Image(ActionKind.ClickImage);Run(new WindowsHost(null,d),s);Check(d.Clicks.SequenceEqual(new[]{new Point(-9,17)}),"Image click used stored coordinates.");}});
            test("Find then LastMatch click works without moving during search",delegate{using(var d=new TestDesktop()){Run(new WindowsHost(null,d),Image(ActionKind.FindImage),new Step{Kind=ActionKind.MouseClick,Pointer=PointerMode.LastMatch,X=-1,Y=-1});Check(d.Clicks.Single()==new Point(-10,16),"Match offset failed.");}});
            test("Current pointer click preserves cursor",delegate{using(var d=new TestDesktop()){d.Move(new Point(44,55));Run(new WindowsHost(null,d),new Step{Kind=ActionKind.MouseClick,Pointer=PointerMode.CurrentPointer});Check(d.Clicks.Single()==new Point(44,55),"Pointer reset.");}});
            test("Failed image clears stale match and never clicks",delegate{using(var d=new TestDesktop()){var h=new WindowsHost(null,d);h.Images.SearchOnce(Image(ActionKind.FindImage),CancellationToken.None);var s=Image(ActionKind.ClickImage);s.Tolerance=0;s.SearchIn=SearchArea.Rectangle;s.X=-20;s.Y=10;s.Width=2;s.Height=2;s.ContinueIfMissing=true;h.Execute(s,CancellationToken.None).GetAwaiter().GetResult();Check(!h.Images.LastMatch.HasValue&&d.Clicks.Count==0,"Stale match retained.");try{h.Images.Position(new Step{Pointer=PointerMode.LastMatch});throw new Exception("Missing match accepted.");}catch(InvalidOperationException){}}});
            test("Nested image IF restores outer match after inner false ELSE",delegate{using(var d=new TestDesktop()){var outer=Image(ActionKind.IfImage);var inner=Image(ActionKind.IfImage);inner.SearchIn=SearchArea.Rectangle;inner.X=-20;inner.Y=10;inner.Width=2;inner.Height=2;Run(new WindowsHost(null,d),outer,inner,new Step{Kind=ActionKind.MouseClick},new Step{Kind=ActionKind.Else},new Step{Kind=ActionKind.Note},new Step{Kind=ActionKind.EndIf},new Step{Kind=ActionKind.MouseClick,Pointer=PointerMode.LastMatch},new Step{Kind=ActionKind.EndIf});Check(d.Clicks.SequenceEqual(new[]{new Point(-9,17)}),"Nested match scope failed.");}});
            test("False outer image IF skips nested missing template entirely",delegate{using(var d=new TestDesktop()){var outer=Image(ActionKind.IfImage);outer.SearchIn=SearchArea.Rectangle;outer.X=-20;outer.Y=10;outer.Width=2;outer.Height=2;Run(new WindowsHost(null,d),outer,new Step{Kind=ActionKind.IfImage,Target="DOES-NOT-EXIST.png"},new Step{Kind=ActionKind.MouseClick},new Step{Kind=ActionKind.EndIf},new Step{Kind=ActionKind.Else},new Step{Kind=ActionKind.MouseClick,X=12,Y=34},new Step{Kind=ActionKind.EndIf});Check(d.Clicks.Single()==new Point(12,34),"Wrong IF branch.");}});
            test("Image wait polls until image appears",delegate{using(var d=new TestDesktop()){d.AppearAfter=3;var s=Image(ActionKind.WaitImage);s.TimeoutMs=200;Run(new WindowsHost(null,d),s);Check(d.Captures==3,"Wait did not poll.");}});
            test("Infinite image wait cancels without clicking",delegate{using(var d=new TestDesktop()){d.AppearAfter=int.MaxValue;var s=Image(ActionKind.ClickImage);s.WaitForever=true;using(var c=new CancellationTokenSource(70)){try{new Runner(new WindowsHost(null,d)).Run(Plan.Build(new Macro{Steps=new List<Step>{s}},directory),1,1,c.Token).GetAwaiter().GetResult();throw new Exception("Not cancelled.");}catch(OperationCanceledException){}Check(d.Clicks.Count==0,"Clicked on missing image.");}}});
            test("Foreground image search translates coordinates",delegate{using(var d=new TestDesktop()){var s=Image(ActionKind.ClickImage);s.SearchIn=SearchArea.ForegroundWindow;Run(new WindowsHost(null,d),s);Check(d.Clicks.Single()==new Point(-9,17),"Window origin lost.");}});
            test("Embedded image survives save and export without source file",delegate{var s=Image(ActionKind.IfImage);string file=Path.Combine(directory,"embedded.json");Storage.Save(file,new Macro{Steps=new List<Step>{s,new Step{Kind=ActionKind.EndIf}}});using(var bitmap=ImageTemplate.Load(Storage.Load(file).Steps[0]))Check(bitmap.Width==2,"Embedded template lost.");});
            test("Transparent mask ignores transparent RGB",delegate{using(var d=new TestDesktop())using(var b=new Bitmap(2,2,PixelFormat.Format32bppArgb)){b.SetPixel(0,0,Color.Red);b.SetPixel(1,0,Color.Transparent);b.SetPixel(0,1,Color.Transparent);b.SetPixel(1,1,Color.Lime);Check(Vision.Match(d.Scene,b,0,CancellationToken.None)==new Point(11,7),"Alpha mask failed.");}});
            test("Entirely transparent template is rejected",delegate{using(var d=new TestDesktop())using(var b=new Bitmap(1,1,PixelFormat.Format32bppArgb)){try{Vision.Match(d.Scene,b,0,CancellationToken.None);throw new Exception("Empty mask accepted.");}catch(InvalidDataException){}}});
            test("Forever playback with control-only steps remains cancellable",delegate{using(var c=new CancellationTokenSource(50)){try{new Runner(new FakeHost()).Run(Plan.Build(new Macro{Steps=new List<Step>{new Step{Kind=ActionKind.Note}}},directory),0,1,c.Token).GetAwaiter().GetResult();throw new Exception("Not cancelled.");}catch(OperationCanceledException){}}});
            test("Forever Repeat supports Break",delegate{var h=new FakeHost();new Runner(h).Run(Plan.Build(new Macro{Steps=new List<Step>{new Step{Kind=ActionKind.Repeat,Count=0},new Step{Kind=ActionKind.TypeText,Text="once"},new Step{Kind=ActionKind.Break},new Step{Kind=ActionKind.EndRepeat}}},directory),1,1,CancellationToken.None).GetAwaiter().GetResult();Check(h.Calls.Count==1,"Forever repeat break failed.");});
            test("Three nested IF levels all branch combinations",delegate{for(int mask=0;mask<8;mask++){using(var d=new TestDesktop()){var steps=new List<Step>();for(int depth=0;depth<3;depth++){var s=Image(ActionKind.IfImage);s.Negate=(mask&(1<<depth))==0;steps.Add(s);}steps.Add(new Step{Kind=ActionKind.MouseClick,Pointer=PointerMode.LastMatch});for(int depth=2;depth>=0;depth--){steps.Add(new Step{Kind=ActionKind.Else});steps.Add(new Step{Kind=ActionKind.MouseClick,X=depth,Y=mask});steps.Add(new Step{Kind=ActionKind.EndIf});}Run(new WindowsHost(null,d),steps.ToArray());Check(d.Clicks.Count==1,"Multiple branches ran.");Point expected=mask==7?new Point(-9,17):new Point((mask&1)==0?0:(mask&2)==0?1:2,mask);Check(d.Clicks[0]==expected,"Wrong nested branch for "+mask);}}});
        }
    }
}
